//! Properties, named configuration sets, and the two resolution chains.
//!
//! CLI-free: this module knows about the environment and the filesystem, but
//! nothing about clap, standout, argv, stdout or exit codes. Callers hand it
//! the per-invocation flag values and read ordinary Rust results back.

use std::collections::BTreeMap;
use std::fmt;
use std::path::{Path, PathBuf};

/// A failure with a user-facing message, reported as a domain error (exit 1).
#[derive(Debug)]
pub struct DomainError(pub String);

impl fmt::Display for DomainError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for DomainError {}

/// A failure in the shape of the command line itself, reported as a usage
/// error (exit 2).
#[derive(Debug)]
pub struct UsageError(pub String);

impl fmt::Display for UsageError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for UsageError {}

/// The three properties this application knows.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Property {
    CoreProject,
    CoreAccount,
    ComputeZone,
}

pub const PROPERTIES: &[Property] = &[
    Property::ComputeZone,
    Property::CoreAccount,
    Property::CoreProject,
];

impl Property {
    pub fn section(self) -> &'static str {
        match self {
            Property::CoreProject | Property::CoreAccount => "core",
            Property::ComputeZone => "compute",
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            Property::CoreProject => "project",
            Property::CoreAccount => "account",
            Property::ComputeZone => "zone",
        }
    }

    pub fn key(self) -> String {
        format!("{}/{}", self.section(), self.name())
    }

    /// `GCLOUDLIKE_CORE_PROJECT` and friends.
    pub fn env_var(self) -> String {
        format!(
            "GCLOUDLIKE_{}_{}",
            self.section().to_uppercase(),
            self.name().to_uppercase()
        )
    }
}

/// A well-formed `<section>/<name>` key, which may still name no property.
pub struct PropertyKey {
    pub section: String,
    pub name: String,
}

impl PropertyKey {
    /// Splits a key at its first `/`. A key with no `/`, or with an empty
    /// section or name, is a usage error.
    pub fn parse(raw: &str) -> Result<PropertyKey, UsageError> {
        let Some((section, name)) = raw.split_once('/') else {
            return Err(UsageError(format!(
                "malformed property key '{raw}': expected <section>/<name>"
            )));
        };
        if section.is_empty() || name.is_empty() {
            return Err(UsageError(format!(
                "malformed property key '{raw}': expected <section>/<name>"
            )));
        }
        Ok(PropertyKey {
            section: section.to_string(),
            name: name.to_string(),
        })
    }

    pub fn as_str(&self) -> String {
        format!("{}/{}", self.section, self.name)
    }

    /// The property this key names, or a domain error when it names none.
    pub fn property(&self) -> Result<Property, DomainError> {
        PROPERTIES
            .iter()
            .copied()
            .find(|property| property.section() == self.section && property.name() == self.name)
            .ok_or_else(|| DomainError(format!("unknown property: {}", self.as_str())))
    }
}

/// The per-invocation flag values that feed step 1 of each chain.
#[derive(Default)]
pub struct Flags {
    pub configuration: Option<String>,
    pub project: Option<String>,
    pub account: Option<String>,
    pub zone: Option<String>,
}

impl Flags {
    fn for_property(&self, property: Property) -> Option<&str> {
        match property {
            Property::CoreProject => self.project.as_deref(),
            Property::CoreAccount => self.account.as_deref(),
            Property::ComputeZone => self.zone.as_deref(),
        }
    }
}

/// An environment variable set to the empty string is treated as unset, as
/// every variable in this application is.
fn env(name: &str) -> Option<String> {
    std::env::var(name).ok().filter(|value| !value.is_empty())
}

/// The parsed contents of one configuration set file.
///
/// Kept as the raw lines plus a section/name index, so that writing a value
/// back can leave every other line of the file exactly as it was.
pub struct ConfigSet {
    lines: Vec<String>,
    /// `section -> name -> (line index, value)`.
    entries: BTreeMap<String, BTreeMap<String, (usize, String)>>,
    /// Whether the file ended with a newline (or did not exist).
    trailing_newline: bool,
}

impl ConfigSet {
    fn parse(contents: &str) -> ConfigSet {
        let trailing_newline = contents.is_empty() || contents.ends_with('\n');
        let mut lines: Vec<String> = contents.lines().map(str::to_string).collect();
        // `lines()` drops the final empty segment; nothing else needs it.
        if lines.last().is_some_and(|line| line.is_empty()) && !trailing_newline {
            lines.pop();
        }

        let mut entries: BTreeMap<String, BTreeMap<String, (usize, String)>> = BTreeMap::new();
        let mut section: Option<String> = None;
        for (index, line) in lines.iter().enumerate() {
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }
            if let Some(header) = trimmed.strip_prefix('[').and_then(|r| r.strip_suffix(']')) {
                section = Some(header.trim().to_string());
                continue;
            }
            let Some(section) = section.as_ref() else {
                continue;
            };
            let Some((name, value)) = line.split_once('=') else {
                continue;
            };
            entries
                .entry(section.clone())
                .or_default()
                .insert(name.trim().to_string(), (index, value.trim().to_string()));
        }

        ConfigSet {
            lines,
            entries,
            trailing_newline,
        }
    }

    fn get(&self, property: Property) -> Option<&str> {
        self.entries
            .get(property.section())
            .and_then(|section| section.get(property.name()))
            .map(|(_, value)| value.as_str())
    }

    /// Replaces the stored value in place, or inserts it into the property's
    /// section, or appends the section — whichever the file calls for. Every
    /// other line survives byte for byte.
    fn set(&mut self, property: Property, value: &str) {
        let entry = format!("{} = {}", property.name(), value);
        if let Some((index, _)) = self
            .entries
            .get(property.section())
            .and_then(|section| section.get(property.name()))
        {
            self.lines[*index] = entry;
            return;
        }
        match self.section_end(property.section()) {
            Some(end) => self.lines.insert(end, entry),
            None => {
                self.lines.push(format!("[{}]", property.section()));
                self.lines.push(entry);
            }
        }
        self.trailing_newline = true;
    }

    /// The index just past the last line belonging to `section`.
    fn section_end(&self, section: &str) -> Option<usize> {
        let mut current: Option<&str> = None;
        let mut end: Option<usize> = None;
        for (index, line) in self.lines.iter().enumerate() {
            let trimmed = line.trim();
            if let Some(header) = trimmed.strip_prefix('[').and_then(|r| r.strip_suffix(']')) {
                if current == Some(section) {
                    return end;
                }
                current = Some(header.trim());
                if current == Some(section) {
                    end = Some(index + 1);
                }
                continue;
            }
            if current == Some(section) && !trimmed.is_empty() {
                end = Some(index + 1);
            }
        }
        end
    }

    fn render(&self) -> String {
        if self.lines.is_empty() {
            return String::new();
        }
        let mut out = self.lines.join("\n");
        if self.trailing_newline {
            out.push('\n');
        }
        out
    }
}

/// The configuration directory and the sets it holds.
pub struct Store {
    root: PathBuf,
}

impl Store {
    /// `$GCLOUDLIKE_CONFIG_DIR` when set and non-empty, otherwise
    /// `$HOME/.config/gcloudlike`.
    pub fn locate() -> Store {
        let root = match env("GCLOUDLIKE_CONFIG_DIR") {
            Some(dir) => PathBuf::from(dir),
            None => {
                let home = std::env::var("HOME").unwrap_or_default();
                Path::new(&home).join(".config").join("gcloudlike")
            }
        };
        Store { root }
    }

    pub fn root(&self) -> &Path {
        &self.root
    }

    fn active_config_path(&self) -> PathBuf {
        self.root.join("active_config")
    }

    fn set_path(&self, name: &str) -> PathBuf {
        self.root.join("configurations").join(format!("config_{name}"))
    }

    /// The set named `default` always exists; any other name exists only if
    /// its file does.
    pub fn exists(&self, name: &str) -> bool {
        name == "default" || self.set_path(name).is_file()
    }

    /// Every existing set, ascending by name.
    pub fn names(&self) -> Vec<String> {
        let mut names: Vec<String> = std::fs::read_dir(self.root.join("configurations"))
            .into_iter()
            .flatten()
            .flatten()
            .filter(|entry| entry.path().is_file())
            .filter_map(|entry| {
                entry
                    .file_name()
                    .to_str()
                    .and_then(|file| file.strip_prefix("config_"))
                    .map(str::to_string)
            })
            .collect();
        if !names.iter().any(|name| name == "default") {
            names.push("default".to_string());
        }
        names.sort();
        names
    }

    pub fn load(&self, name: &str) -> ConfigSet {
        let contents = std::fs::read_to_string(self.set_path(name)).unwrap_or_default();
        ConfigSet::parse(&contents)
    }

    fn store(&self, name: &str, set: &ConfigSet) -> std::io::Result<()> {
        let path = self.set_path(name);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(path, set.render())
    }

    /// Creates an empty set. An existing name is a domain error, and nothing
    /// is written.
    pub fn create(&self, name: &str) -> Result<(), DomainError> {
        if self.exists(name) {
            return Err(DomainError(format!(
                "configuration already exists: {name}"
            )));
        }
        self.store(name, &ConfigSet::parse(""))
            .map_err(|error| DomainError(format!("cannot create configuration {name}: {error}")))
    }

    /// Writes `name` into `active_config`. The set must exist.
    pub fn activate(&self, name: &str) -> Result<(), DomainError> {
        if !self.exists(name) {
            return Err(DomainError(format!("unknown configuration: {name}")));
        }
        std::fs::create_dir_all(&self.root)
            .and_then(|()| std::fs::write(self.active_config_path(), format!("{name}\n")))
            .map_err(|error| DomainError(format!("cannot activate configuration {name}: {error}")))
    }

    /// The persisted active set. Absent or empty means `default`.
    fn persisted_active(&self) -> String {
        std::fs::read_to_string(self.active_config_path())
            .ok()
            .and_then(|contents| contents.lines().next().map(str::trim).map(str::to_string))
            .filter(|name| !name.is_empty())
            .unwrap_or_else(|| "default".to_string())
    }
}

/// Everything one invocation decided: which set is active, and what each
/// property's effective value is.
pub struct Session {
    pub store: Store,
    pub active: String,
    values: BTreeMap<String, String>,
}

impl Session {
    /// Runs both chains. They stay separate: `--configuration` and
    /// `GCLOUDLIKE_ACTIVE_CONFIG` only ever name a set, and a
    /// `GCLOUDLIKE_<SECTION>_<NAME>` variable only ever supplies a property.
    pub fn resolve(flags: &Flags) -> Result<Session, DomainError> {
        let store = Store::locate();

        let active = flags
            .configuration
            .clone()
            .or_else(|| env("GCLOUDLIKE_ACTIVE_CONFIG"))
            .unwrap_or_else(|| store.persisted_active());
        if !store.exists(&active) {
            return Err(DomainError(format!("unknown configuration: {active}")));
        }

        // A set applies whole: only this one is ever read.
        let set = store.load(&active);
        let mut values = BTreeMap::new();
        for property in PROPERTIES.iter().copied() {
            let value = flags
                .for_property(property)
                .map(str::to_string)
                .or_else(|| env(&property.env_var()))
                .or_else(|| set.get(property).map(str::to_string));
            if let Some(value) = value {
                values.insert(property.key(), value);
            }
        }

        Ok(Session {
            store,
            active,
            values,
        })
    }

    pub fn get(&self, property: Property) -> Option<&str> {
        self.values.get(&property.key()).map(String::as_str)
    }

    /// The effective value, or the domain error that names it unset.
    pub fn require(&self, property: Property) -> Result<&str, DomainError> {
        self.get(property)
            .ok_or_else(|| DomainError(format!("unset property: {}", property.key())))
    }

    /// The effective properties, grouped by section — both orders ascending,
    /// and sections without an effective property left out.
    pub fn effective(&self) -> BTreeMap<String, BTreeMap<String, String>> {
        let mut sections: BTreeMap<String, BTreeMap<String, String>> = BTreeMap::new();
        for property in PROPERTIES.iter().copied() {
            if let Some(value) = self.get(property) {
                sections
                    .entry(property.section().to_string())
                    .or_default()
                    .insert(property.name().to_string(), value.to_string());
            }
        }
        sections
    }

    /// Stores a value for `property` in the active set.
    pub fn set(&self, property: Property, value: &str) -> Result<(), DomainError> {
        let mut set = self.store.load(&self.active);
        set.set(property, value);
        self.store
            .store(&self.active, &set)
            .map_err(|error| DomainError(format!("cannot write configuration: {error}")))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_trimmed_ini_entries() {
        let set = ConfigSet::parse("[core]\n  project   =  alpha-proj  \n\n[compute]\nzone = us-a1\n");
        assert_eq!(set.get(Property::CoreProject), Some("alpha-proj"));
        assert_eq!(set.get(Property::ComputeZone), Some("us-a1"));
        assert_eq!(set.get(Property::CoreAccount), None);
    }

    #[test]
    fn a_value_is_the_rest_of_the_line_after_the_first_equals() {
        let set = ConfigSet::parse("[core]\naccount = a=b=c\n");
        assert_eq!(set.get(Property::CoreAccount), Some("a=b=c"));
    }

    #[test]
    fn replacing_a_value_leaves_every_other_line_alone() {
        let mut set = ConfigSet::parse("[other]\nkeep = me\n\n[core]\nproject = old\naccount = who\n");
        set.set(Property::CoreProject, "new");
        assert_eq!(
            set.render(),
            "[other]\nkeep = me\n\n[core]\nproject = new\naccount = who\n"
        );
    }

    #[test]
    fn a_new_property_joins_its_existing_section() {
        let mut set = ConfigSet::parse("[core]\nproject = p\n\n[compute]\nzone = z\n");
        set.set(Property::CoreAccount, "me@example.com");
        assert_eq!(
            set.render(),
            "[core]\nproject = p\naccount = me@example.com\n\n[compute]\nzone = z\n"
        );
    }

    #[test]
    fn a_new_section_is_appended() {
        let mut set = ConfigSet::parse("[core]\nproject = p\n");
        set.set(Property::ComputeZone, "us-a1");
        assert_eq!(set.render(), "[core]\nproject = p\n[compute]\nzone = us-a1\n");
    }

    #[test]
    fn an_empty_set_gains_a_section() {
        let mut set = ConfigSet::parse("");
        set.set(Property::CoreProject, "alpha-proj");
        assert_eq!(set.render(), "[core]\nproject = alpha-proj\n");
    }

    #[test]
    fn a_key_needs_a_slash_and_two_non_empty_halves() {
        assert!(PropertyKey::parse("project").is_err());
        assert!(PropertyKey::parse("/project").is_err());
        assert!(PropertyKey::parse("core/").is_err());
        let key = PropertyKey::parse("core/project").unwrap();
        assert_eq!(key.section, "core");
        assert_eq!(key.name, "project");
    }

    #[test]
    fn a_well_formed_key_outside_the_table_is_a_domain_error() {
        let key = PropertyKey::parse("core/nope").unwrap();
        assert!(key.property().is_err());
    }
}

