//! CLI adapters. Each one reads the invocation's resolved `Session` out of the
//! context, calls the CLI-free modules, and returns serializable view data.

use standout::cli::{Artifact, CommandContext, ExternalFailure, Output};
use standout::handler;

use crate::inventory;
use crate::settings::{DomainError, Property, PropertyKey, Session};
use crate::views::*;

/// Turns a domain failure into the one stderr line and exit status 1 the
/// application's contract declares. `ExternalFailure` is the seam that keeps
/// the payload verbatim — Standout's own `Error: ` framing would not match.
pub fn domain(error: DomainError) -> anyhow::Error {
    match ExternalFailure::new(1, format!("gcloudlike: {error}\n")) {
        Ok(failure) => failure.into(),
        // Unreachable: construction only rejects status 0.
        Err(error) => anyhow::Error::new(error),
    }
}

fn session<'a>(ctx: &'a CommandContext) -> Result<&'a Session, anyhow::Error> {
    ctx.extensions.get_required::<Session>()
}

/// The notice these three commands write to stderr, or nothing under `--quiet`.
fn notice<T: serde::Serialize>(report: T, quiet: bool) -> Output<T> {
    if quiet {
        Output::Silent
    } else {
        Output::Artifact(
            Artifact::new(Vec::new())
                .allow_stdout()
                .with_report(report),
        )
    }
}

pub mod instances {
    use super::*;

    #[handler]
    pub fn list(#[ctx] ctx: &CommandContext) -> Result<Output<InstanceListView>, anyhow::Error> {
        let session = session(ctx)?;
        let project = session.require(Property::CoreProject).map_err(domain)?;
        let zone = session.get(Property::ComputeZone);

        let instances = inventory::list(project, zone)
            .into_iter()
            .map(InstanceRow::from)
            .collect();
        Ok(Output::Render(InstanceListView { instances }))
    }

    #[handler]
    pub fn describe(
        #[arg] name: String,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<InstanceView>, anyhow::Error> {
        let session = session(ctx)?;
        let project = session.require(Property::CoreProject).map_err(domain)?;

        let instance = inventory::describe(project, &name)
            .ok_or_else(|| DomainError(format!("no such instance: {name}")))
            .map_err(domain)?;
        Ok(Output::Render(InstanceView::from(instance)))
    }
}

pub mod config {
    use super::*;

    #[handler]
    pub fn get_value(
        #[arg] property: String,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<ValueView>, anyhow::Error> {
        let session = session(ctx)?;
        // Well-formedness was already settled by the argument's value parser.
        let key = PropertyKey::parse(&property).map_err(|error| anyhow::anyhow!("{error}"))?;
        let property = key.property().map_err(domain)?;

        let value = session.require(property).map_err(domain)?;
        Ok(Output::Render(ValueView {
            value: value.to_string(),
        }))
    }

    #[handler]
    pub fn set(
        #[arg] property: String,
        #[arg] value: String,
        #[flag] quiet: bool,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<UpdatedNotice>, anyhow::Error> {
        let session = session(ctx)?;
        let key = PropertyKey::parse(&property).map_err(|error| anyhow::anyhow!("{error}"))?;
        let property = key.property().map_err(domain)?;

        session.set(property, &value).map_err(domain)?;
        Ok(notice(
            UpdatedNotice {
                property: property.key(),
            },
            quiet,
        ))
    }

    #[handler]
    pub fn list(#[ctx] ctx: &CommandContext) -> Result<Output<ConfigListView>, anyhow::Error> {
        let sections = session(ctx)?
            .effective()
            .into_iter()
            .map(|(section, properties)| SectionView {
                section,
                properties: properties
                    .into_iter()
                    .map(|(name, value)| PropertyView { name, value })
                    .collect(),
            })
            .collect();
        Ok(Output::Render(ConfigListView { sections }))
    }
}

pub mod configurations {
    use super::*;

    #[handler]
    pub fn list(
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<ConfigurationListView>, anyhow::Error> {
        let session = session(ctx)?;
        let configurations = session
            .store
            .names()
            .into_iter()
            .map(|name| ConfigurationView {
                is_active: name == session.active,
                name,
            })
            .collect();
        Ok(Output::Render(ConfigurationListView { configurations }))
    }

    #[handler]
    pub fn create(
        #[arg] name: String,
        #[flag] quiet: bool,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<ConfigurationNotice>, anyhow::Error> {
        session(ctx)?.store.create(&name).map_err(domain)?;
        Ok(notice(ConfigurationNotice { name }, quiet))
    }

    #[handler]
    pub fn activate(
        #[arg] name: String,
        #[flag] quiet: bool,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<ConfigurationNotice>, anyhow::Error> {
        session(ctx)?.store.activate(&name).map_err(domain)?;
        Ok(notice(ConfigurationNotice { name }, quiet))
    }
}

