use standout::cli::{App, CommandContext, Dispatch, ExternalFailure, HookError, Hooks};
use standout::{embed_styles, embed_templates};

use settings::{Flags, PropertyKey, Session};

#[derive(Parser)]
#[command(name = "gcloudlike", about = "A tiny cloud-inventory CLI.")]
struct Cli {
    /// Name the configuration set this invocation uses.
    #[arg(long, global = true, value_name = "NAME")]
    configuration: Option<String>,

    /// Supply core/project for this invocation.
    #[arg(long, global = true, value_name = "PROJECT")]
    project: Option<String>,

    /// Supply core/account for this invocation.
    #[arg(long, global = true, value_name = "ACCOUNT")]
    account: Option<String>,

    /// Supply compute/zone for this invocation.
    #[arg(long, global = true, value_name = "ZONE")]
    zone: Option<String>,

    /// Select the human form (`text`) or the machine projection (`json`).
    #[arg(long, global = true, value_name = "FORM", value_parser = ["text", "json"])]
    format: Option<String>,

    /// Suppress the stderr notice of a command that writes one.
    #[arg(long, global = true)]
    quiet: bool,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers)]
enum Commands {
    /// Compute Engine resources.
    #[command(subcommand)]
    #[dispatch(nested)]
    Compute(ComputeCommands),

    /// Properties and configuration sets.
    #[command(subcommand)]
    #[dispatch(nested)]
    Config(ConfigCommands),
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers)]
enum ComputeCommands {
    /// Instances of the effective project.
    #[command(subcommand)]
    #[dispatch(nested)]
    Instances(InstancesCommands),
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers::instances)]
enum InstancesCommands {
    /// List the instances of the effective project.
    #[dispatch(pure)]
    List,

    /// Describe one instance of the effective project.
    #[dispatch(pure)]
    Describe {
        /// The instance name.
        name: String,
    },
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers::config)]
enum ConfigCommands {
    /// Print the effective value of a property.
    #[dispatch(pure)]
    GetValue {
        /// The property, spelled `<section>/<name>`.
        #[arg(value_parser = well_formed_key)]
        property: String,
    },

    /// Store a property's value in the active configuration set.
    #[dispatch(pure)]
    Set {
        /// The property, spelled `<section>/<name>`.
        #[arg(value_parser = well_formed_key)]
        property: String,
        /// The value to store.
        value: String,
    },

    /// Print the effective properties of this invocation.
    #[dispatch(pure)]
    List,

    /// Named configuration sets.
    #[command(subcommand)]
    #[dispatch(nested)]
    Configurations(ConfigurationsCommands),
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers::configurations)]
enum ConfigurationsCommands {
    /// List every existing configuration set.
    #[dispatch(pure)]
    List,

    /// Create an empty configuration set.
    #[dispatch(pure)]
    Create {
        /// The set name.
        name: String,
    },

    /// Make a configuration set the persisted active one.
    #[dispatch(pure)]
    Activate {
        /// The set name.
        name: String,
    },
