        .map(|_| raw.to_string())
        .map_err(|error| error.to_string())
}

/// Every registered command path, in the order the tree declares them.
const COMMAND_PATHS: &[&str] = &[
    "compute.instances.list",
    "compute.instances.describe",
    "config.get-value",
    "config.set",
    "config.list",
    "config.configurations.list",
    "config.configurations.create",
    "config.configurations.activate",
];

/// Reads a global option wherever clap left it, root or deepest.
fn global_value(matches: &ArgMatches, id: &str) -> Option<String> {
    if let Ok(Some(value)) = matches.try_get_one::<String>(id) {
        return Some(value.clone());
    }
    matches
        .subcommand()
        .and_then(|(_, sub)| global_value(sub, id))
}

/// Resolves both chains once per invocation, before any handler runs, and
/// leaves the result in the per-request extensions.
fn open_session(matches: &ArgMatches, ctx: &mut CommandContext) -> Result<(), HookError> {
    let flags = Flags {
        configuration: global_value(matches, "configuration"),
        project: global_value(matches, "project"),
        account: global_value(matches, "account"),
        zone: global_value(matches, "zone"),
    };

    match Session::resolve(&flags) {
        Ok(session) => {
            ctx.extensions.insert(session);
            Ok(())
        }
        Err(error) => {
            let failure = ExternalFailure::new(1, format!("gcloudlike: {error}\n"))
                .expect("1 is a nonzero status");
            Err(HookError::pre_dispatch_external(failure))
        }
    }
}

/// The structured modes `--output` can name.
const STRUCTURED: &[&str] = &["json", "yaml", "xml", "csv"];

/// `--format` and `--output` claim the same stdout, and the application's
/// `--format` decides. Both flags stay real — `--output` is Standout's, and
/// this only settles the argument they disagree about.
fn reconcile_output(args: Vec<String>) -> Vec<String> {
    let mut format = None;
    let mut output = None;
    let mut index = 1;
    while index < args.len() {
        let arg = args[index].as_str();
        if arg == "--" {
            break;
        }
        if let Some(value) = arg.strip_prefix("--format=") {
            format = Some(value.to_string());
        } else if arg == "--format" {
            format = args.get(index + 1).cloned();
            index += 1;
        } else if let Some(value) = arg.strip_prefix("--output=") {
            output = Some(value.to_string());
        } else if arg == "--output" {
            output = args.get(index + 1).cloned();
            index += 1;
        }
        index += 1;
    }

    let forced = match format.as_deref() {
        // The machine projection, whatever `--output` asked for.
        Some("json") => "json",
        // The human form; `--output text|term|auto` still chooses the styling,
        // and only a structured `--output` has to give way.
        Some("text") if output.as_deref().is_some_and(|m| STRUCTURED.contains(&m)) => "text",
        _ => return args,
    };

    let mut reconciled = Vec::with_capacity(args.len() + 1);
    let mut index = 0;
    let mut positional_only = false;
    while index < args.len() {
        let arg = args[index].as_str();
        if positional_only || index == 0 {
            reconciled.push(args[index].clone());
        } else if arg == "--" {
            positional_only = true;
            reconciled.push(args[index].clone());
        } else if arg.starts_with("--output=") {
            // dropped
        } else if arg == "--output" {
            index += 1; // drop its value too
        } else {
            reconciled.push(args[index].clone());
        }
        index += 1;
    }
    reconciled.push(format!("--output={forced}"));
    reconciled
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut builder = App::builder()
        .version(env!("CARGO_PKG_VERSION"))
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme("default")
        .commands(Commands::dispatch_config())?;

    for path in COMMAND_PATHS {
        builder = builder.hooks(*path, Hooks::new().pre_dispatch(open_session));
    }

    let app = builder.build()?;
    let args = reconcile_output(std::env::args().collect());
    app.run(Cli::command(), args);
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn argv(line: &[&str]) -> Vec<String> {
        std::iter::once("gcloudlike")
            .chain(line.iter().copied())
            .map(str::to_string)
            .collect()
    }

    #[test]
    fn a_line_naming_neither_form_is_left_alone() {
        assert_eq!(reconcile_output(argv(&["config", "list"])), argv(&["config", "list"]));
        assert_eq!(
            reconcile_output(argv(&["config", "list", "--output", "term"])),
            argv(&["config", "list", "--output", "term"])
        );
    }

    #[test]
    fn format_json_wins_over_any_output() {
        assert_eq!(
            reconcile_output(argv(&["config", "list", "--format", "json", "--output", "text"])),
            argv(&["config", "list", "--format", "json", "--output=json"])
        );
        assert_eq!(
            reconcile_output(argv(&["config", "list", "--format=json"])),
            argv(&["config", "list", "--format=json", "--output=json"])
        );
    }

    #[test]
    fn format_text_only_displaces_a_structured_output() {
        assert_eq!(
            reconcile_output(argv(&["config", "list", "--format", "text", "--output=json"])),
            argv(&["config", "list", "--format", "text", "--output=text"])
        );
        assert_eq!(
            reconcile_output(argv(&["config", "list", "--format", "text", "--output", "term"])),
            argv(&["config", "list", "--format", "text", "--output", "term"])
        );
    }

    #[test]
    fn output_file_path_is_not_the_output_flag() {
        assert_eq!(
            reconcile_output(argv(&["config", "list", "--format=json", "--output-file-path=x"])),
            argv(&["config", "list", "--format=json", "--output-file-path=x", "--output=json"])
        );
    }
}

